70	@RestController
71	@CrossOrigin(exposedHeaders = "errors, content-type")
72	@RequestMapping("/api")
73	public class OwnerRestControllerV1 implements OwnersApi {
74	
75	    private final ClinicService clinicService;
76	
77	    private final OwnerMapper ownerMapper;
78	
79	    private final PetMapper petMapper;
80	
81	    private final VisitMapper visitMapper;
82	
83	    private final OwnerFieldsValidator ownerFieldsValidator;
84	
85	    private final RegistrationDateValidator registrationDateValidator;
86	
87	    private final RegistrationDateAssigner registrationDateAssigner;
88	
89	    private final CustomerCodeAssigner customerCodeAssigner;
90	
91	    private final HouseholdDuplicateChecker householdDuplicateChecker;
92	
93	    private final IdentityDuplicateChecker identityDuplicateChecker;
94	
95	    private final HouseholdAssigner householdAssigner;
96	
97	    private final HouseholdSizeAssigner householdSizeAssigner;
98	
99	    private final NamesakeCounter namesakeCounter;
100	
101	    private final MembershipLevelAssigner membershipLevelAssigner;
102	
103	    private final CityCapacityChecker cityCapacityChecker;
104	
105	    private final DailyRegistrationLimiter dailyRegistrationLimiter;
106	
107	    private final BulkSignupWarningAssigner bulkSignupWarningAssigner;
108	
109	    private final OwnerCreationAuditLogger ownerCreationAuditLogger;
110	
111	    private final PossibleDuplicateAssigner possibleDuplicateAssigner;
112	
113	    private final IdempotentOwnerStore idempotentOwnerStore;
114	
115	    public OwnerRestControllerV1(ClinicService clinicService,
116	                                 OwnerMapper ownerMapper,
117	                                 PetMapper petMapper,
118	                                 VisitMapper visitMapper,
119	                                 OwnerFieldsValidator ownerFieldsValidator,
120	                                 RegistrationDateValidator registrationDateValidator,
121	                                 RegistrationDateAssigner registrationDateAssigner,
122	                                 CustomerCodeAssigner customerCodeAssigner,
123	                                 HouseholdDuplicateChecker householdDuplicateChecker,
124	                                 IdentityDuplicateChecker identityDuplicateChecker,
125	                                 HouseholdAssigner householdAssigner,
126	                                 HouseholdSizeAssigner householdSizeAssigner,
127	                                 NamesakeCounter namesakeCounter,
128	                                 MembershipLevelAssigner membershipLevelAssigner,
129	                                 CityCapacityChecker cityCapacityChecker,
130	                                 DailyRegistrationLimiter dailyRegistrationLimiter,
131	                                 BulkSignupWarningAssigner bulkSignupWarningAssigner,
132	                                 OwnerCreationAuditLogger ownerCreationAuditLogger,
133	                                 PossibleDuplicateAssigner possibleDuplicateAssigner,
134	                                 IdempotentOwnerStore idempotentOwnerStore) {
135	        this.clinicService = clinicService;
136	        this.ownerMapper = ownerMapper;
137	        this.petMapper = petMapper;
138	        this.visitMapper = visitMapper;
139	        this.ownerFieldsValidator = ownerFieldsValidator;
140	        this.registrationDateValidator = registrationDateValidator;
141	        this.registrationDateAssigner = registrationDateAssigner;
142	        this.customerCodeAssigner = customerCodeAssigner;
143	        this.householdDuplicateChecker = householdDuplicateChecker;
144	        this.identityDuplicateChecker = identityDuplicateChecker;
145	        this.householdAssigner = householdAssigner;
146	        this.householdSizeAssigner = householdSizeAssigner;
147	        this.namesakeCounter = namesakeCounter;
148	        this.membershipLevelAssigner = membershipLevelAssigner;
149	        this.cityCapacityChecker = cityCapacityChecker;
150	        this.dailyRegistrationLimiter = dailyRegistrationLimiter;
151	        this.bulkSignupWarningAssigner = bulkSignupWarningAssigner;
152	        this.ownerCreationAuditLogger = ownerCreationAuditLogger;
153	        this.possibleDuplicateAssigner = possibleDuplicateAssigner;
154	        this.idempotentOwnerStore = idempotentOwnerStore;
155	    }
156	
157	    @InitBinder("ownerFieldsDto")
158	    void initOwnerFieldsBinder(WebDataBinder binder) {
159	        binder.addValidators(ownerFieldsValidator, registrationDateValidator);
160	    }
161	
162	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
163	    @Override
164	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
165	        Collection<Owner> owners;
166	        if (lastName != null) {
167	            owners = this.clinicService.findOwnerByLastName(lastName);
168	        } else {
169	            owners = this.clinicService.findAllOwners();
170	        }
171	        if (owners.isEmpty()) {
172	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
173	        }
174	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
175	    }
176	
177	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
178	    @Override
179	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
180	        Owner owner = this.clinicService.findOwnerById(ownerId);
181	        if (owner == null) {
182	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
183	        }
184	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
185	    }
186	
187	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
188	    @Override
189	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto, String idempotencyKey) {
190	        if (StringUtils.hasText(idempotencyKey)) {
191	            Owner original = this.idempotentOwnerStore.find(idempotencyKey)
192	                .map(this.clinicService::findOwnerById)
193	                .orElse(null);
194	            if (original != null) {
195	                return new ResponseEntity<>(ownerMapper.toOwnerDto(original), HttpStatus.OK);
196	            }
197	        }
198	        HttpHeaders headers = new HttpHeaders();
199	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
200	        this.registrationDateAssigner.assign(owner);
201	        if (this.cityCapacityChecker.isCityAtCapacity(owner)) {
202	            return new ResponseEntity<>(HttpStatus.CONFLICT);
203	        }
204	        if (this.dailyRegistrationLimiter.isDailyLimitReached(owner.getRegistrationDate())) {
205	            return new ResponseEntity<>(HttpStatus.TOO_MANY_REQUESTS);
206	        }
207	        this.householdAssigner.assign(owner);
208	        boolean sharesHousehold = Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold());
209	        boolean householdDuplicate = this.householdDuplicateChecker.isDuplicate(owner);
210	        if (householdDuplicate && !sharesHousehold) {
211	            return new ResponseEntity<>(HttpStatus.CONFLICT);
212	        }
213	        if (this.identityDuplicateChecker.isDuplicate(owner)) {
214	            return new ResponseEntity<>(HttpStatus.CONFLICT);
215	        }
216	        boolean declaredHouseholdMember = householdDuplicate && sharesHousehold;
217	        this.householdSizeAssigner.assign(owner);
218	        this.customerCodeAssigner.assign(owner);
219	        this.namesakeCounter.assign(owner);
220	        this.membershipLevelAssigner.assign(owner);
221	        this.bulkSignupWarningAssigner.assign(owner);
222	        this.possibleDuplicateAssigner.assign(owner, declaredHouseholdMember);
223	        this.clinicService.saveOwner(owner);
224	        if (StringUtils.hasText(idempotencyKey)) {
225	            this.idempotentOwnerStore.remember(idempotencyKey, owner);
226	        }
227	        this.ownerCreationAuditLogger.logCreated(owner);
228	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
229	        headers.setLocation(UriComponentsBuilder.newInstance()
230	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
231	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
232	    }
233	
234	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
235	    @Override
236	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
237	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
238	        if (currentOwner == null) {
239	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
240	        }
241	        currentOwner.setAddress(ownerFieldsDto.getAddress());
242	        currentOwner.setAddressLine1(ownerFieldsDto.getAddressLine1());
243	        currentOwner.setAddressLine2(ownerFieldsDto.getAddressLine2());
244	        currentOwner.setCity(ownerFieldsDto.getCity());
245	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
246	        currentOwner.setLastName(ownerFieldsDto.getLastName());
247	        currentOwner.setTelephone(ownerFieldsDto.getTelephone());
248	        currentOwner.setEmail(ownerFieldsDto.getEmail());
249	        this.clinicService.saveOwner(currentOwner);
250	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
251	    }
252	
253	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
254	    @Transactional
255	    @Override
256	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
257	        Owner owner = this.clinicService.findOwnerById(ownerId);
258	        if (owner == null) {
259	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
260	        }
261	        this.clinicService.deleteOwner(owner);
262	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
263	    }
264	
265	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
266	    @Override
267	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
268	        Owner owner = this.clinicService.findOwnerById(ownerId);
269	        if (owner == null) {
270	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
271	        }
272	        HttpHeaders headers = new HttpHeaders();
273	        Pet pet = petMapper.toPet(petFieldsDto);
274	        owner.setId(ownerId);
275	        pet.setOwner(owner);
276	        pet.getType().setName(null);
277	        this.clinicService.savePet(pet);
278	        PetDto petDto = petMapper.toPetDto(pet);
279	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
280	            .buildAndExpand(pet.getId()).toUri());
281	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
282	    }
283	
284	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
285	    @Override
286	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
287	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
288	        if (currentOwner != null) {
289	            Pet currentPet = this.clinicService.findPetById(petId);
290	            if (currentPet != null) {
291	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
292	                currentPet.setName(petFieldsDto.getName());
293	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
294	                this.clinicService.savePet(currentPet);
295	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
296	            }
297	        }
298	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
299	    }
300	
301	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
302	    @Override
303	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
304	        HttpHeaders headers = new HttpHeaders();
305	        Visit visit = visitMapper.toVisit(visitFieldsDto);
306	        Pet pet = new Pet();
307	        pet.setId(petId);
308	        visit.setPet(pet);
309	        this.clinicService.saveVisit(visit);
310	        VisitDto visitDto = visitMapper.toVisitDto(visit);
311	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
312	            .buildAndExpand(visit.getId()).toUri());
313	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
314	    }
315	
316	
317	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
318	    @Override
319	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
320	        Owner owner = this.clinicService.findOwnerById(ownerId);
321	        if (owner != null) {
322	            Pet pet = owner.getPet(petId);
323	            if (pet != null) {
324	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
325	            }
326	        }
327	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
328	    }
329	}
