        LocalDate effectiveDate = owner.getRegistrationDate() != null
            ? owner.getRegistrationDate()
            : LocalDate.now(clock);
        owner.setRegistrationDate(businessDayAdjuster.toBusinessDay(effectiveDate));
    }
}

