18	
19	import java.util.Set;
20	import java.util.stream.Collectors;
21	
22	import org.springframework.samples.petclinic.model.Owner;
23	import org.springframework.samples.petclinic.model.Sha256Hex;
24	import org.springframework.samples.petclinic.service.ClinicService;
25	import org.springframework.stereotype.Component;
26	
27	/**
28	 * Assigns an owner's customer code on create.
29	 * <p>
30	 * The code is formatted {@code <REGION>-<HASH8>} where {@code REGION} is the owner's
31	 * {@link Owner#getRegion() region} (derived from its postcode, falling back to its city)
32	 * and {@code HASH8} is the first 8 upper-case hex characters of the SHA-256 digest of the
33	 * owner's normalized telephone concatenated with its last name (e.g. {@code "NSW-1A2B3C4D"}).
34	 * <p>
35	 * When the computed code collides with an already-stored owner's customer code, it is
36	 * de-duplicated by appending {@code -<n>} with the smallest {@code n} of 2 or more that
37	 * makes it unique.
38	 */
39	@Component
40	public class CustomerCodeAssigner {
41	
42	    /** Number of leading hex characters of the identity hash kept in the customer code. */
43	    private static final int HASH_LENGTH = 8;
44	
45	    private final ClinicService clinicService;
46	
47	    public CustomerCodeAssigner(ClinicService clinicService) {
48	        this.clinicService = clinicService;
49	    }
50	
51	    /**
52	     * Assigns {@code owner}'s customer code from its region and the hash of its normalized
53	     * telephone and last name, de-duplicated against already-stored owners. Call this after
54	     * the telephone has been normalized and before the owner is saved.
55	     *
56	     * @param owner the owner being created
57	     */
58	    public void assign(Owner owner) {
59	        String base = owner.getRegion() + "-"
60	            + Sha256Hex.prefix(owner.getTelephone() + owner.getLastName(), HASH_LENGTH);
61	        owner.setCustomerCode(deduplicate(base));
62	    }
63	
64	    private String deduplicate(String base) {
65	        Set<String> existing = clinicService.findAllOwners().stream()
66	            .map(Owner::getCustomerCode)
67	            .collect(Collectors.toSet());
68	        if (!existing.contains(base)) {
69	            return base;
70	        }
71	        int n = 2;
72	        while (existing.contains(base + "-" + n)) {
73	            n++;
74	        }
75	        return base + "-" + n;
76	    }
77	}
